package com.mediconnect.prescription.domain;
import java.util.*; import com.mediconnect.appointment.domain.AppointmentEntity; import com.mediconnect.doctor.domain.DoctorEntity; import com.mediconnect.patient.domain.PatientEntity; import com.mediconnect.shared.audit.AuditableEntity; import jakarta.persistence.*;
@Entity @Table(name="prescriptions") public class PrescriptionEntity extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="appointment_id",nullable=false) private AppointmentEntity appointment; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="doctor_id",nullable=false) private DoctorEntity doctor; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id",nullable=false) private PatientEntity patient; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private MedicationValidationStatus validationStatus; @OneToMany(mappedBy="prescription",cascade=CascadeType.ALL,orphanRemoval=true) private List<PrescriptionItemEntity> items=new ArrayList<>(); protected PrescriptionEntity(){} public PrescriptionEntity(AppointmentEntity appointment,MedicationValidationStatus validationStatus){this.appointment=appointment;this.doctor=appointment.getDoctor();this.patient=appointment.getPatient();this.validationStatus=validationStatus;} public void addItem(PrescriptionItemEntity item){item.assignTo(this);items.add(item);} public UUID getId(){return id;} public AppointmentEntity getAppointment(){return appointment;} public DoctorEntity getDoctor(){return doctor;} public PatientEntity getPatient(){return patient;} public MedicationValidationStatus getValidationStatus(){return validationStatus;} public List<PrescriptionItemEntity> getItems(){return items;} }
